<script setup lang="ts">
// generated by AI (GitHub Copilot, DeepSeek V4 Flash Vision Exp)
// Sync button: runs the merge-based sync and reports the outcome.

import { n, t } from '@nextcloud/l10n';
import { ref } from 'vue';

import { ReadOnlyError } from '../storage/remote';
import type { SyncResult } from '../sync/syncController';
import { sync } from '../sync/syncController';
import {
  activeDescriptor,
  currentDatabase,
  currentKey,
  setDatabase,
  touch,
} from '../state/session';
import { notify } from './notify';

const busy = ref(false);

/** Human-readable summary of a sync outcome. */
function outcomeMessage(result: SyncResult): string {
  switch (result.outcome) {
    case 'up-to-date':
      return t('upm', 'Already up to date.');
    case 'downloaded':
      return t('upm', 'Downloaded the newer remote database.');
    case 'uploaded':
      return t('upm', 'Uploaded your changes.');
    case 'merged':
      return result.conflictCount > 0
        ? n(
            'upm',
            '%n conflicting account kept as a copy',
            '%n conflicting accounts kept as copies',
            result.conflictCount,
          )
        : t('upm', 'Databases merged.');
  }
  return t('upm', 'Sync complete.');
}

async function run(): Promise<void> {
  const db = currentDatabase.value;
  const key = currentKey.value;
  const descriptor = activeDescriptor.value;
  if (!db || key === null || !descriptor || busy.value) {
    return;
  }
  if (descriptor.id === '') {
    notify(t('upm', 'Save the database before syncing.'));
    return;
  }
  busy.value = true;
  try {
    const result = await sync(db, key, descriptor);
    setDatabase(result.database, key, descriptor);
    notify(outcomeMessage(result));
  } catch (error) {
    notify(
      error instanceof ReadOnlyError
        ? t('upm', 'This database is read-only.')
        : t('upm', 'Sync failed. Check your connection and try again.'),
    );
  } finally {
    busy.value = false;
    touch();
  }
}
</script>

<template>
  <button type="button" class="button" :disabled="busy" @click="run">
    {{ busy ? t('upm', 'Syncing…') : t('upm', 'Sync') }}
  </button>
</template>
